    "difficulty": "easy",
    "passage": "Fans of science fiction will ______ multiple references to classic sci-fi stories in Janelle Monáe’s song lyrics, including her recurring nods to the plot of the 1927 sci-fi film Metropolis.",
    "stem": "Which choice completes the text so that it conforms to the conventions of Standard English?",
