    "subtopic": "Boundaries & punctuation",
    "difficulty": "medium",
    "passage": "In Puerto Rico, it’s not unusual for a city or town to be known by a nickname that corresponds to one of its notable features, like landscape, climate, famous residents, or chief export. For example, the Puerto Rican municipality of Aibonito is well known for its lush ______ this distinction has earned it the fitting nickname of “the Garden of Puerto Rico. ”",
