    "subtopic": "Boundaries & punctuation",
    "difficulty": "hard",
    "passage": "The Balkan nation of Bosnia and Herzegovina does not have one president but ______ as members of the office of the presidency, one representing the nation’s Bosniaks, one its Serbs, and one its Croats, these elected officials take turns serving as the office’s chairperson.",
