    "correctAnswer": "B",
    "explanation": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb \"though\"from the preceding main clause (\"They are hardly pristine\") and uses a semicolon to join the two main clauses (\"They…though\"and \"many…objects\"). Further, placing the semicolon after \"though\"indicates that the information in the preceding main clause (chondrites are far from pristine) is contrary to what might be assumed from the information in the previous sentence (chondrites have been generally unaltered by their environment).\n Choice A is incorrect because placing the comma after \"pristine\"and using \"though\"as a subordinating conjunction illogically indicates that the information in the next main clause (many chondrites have experienced damage) is contrary to the information in the previous clause (chondrites are far from pristine).\n Choice C is incorrect because placing the semicolon after \"pristine\"illogically indicates that the information in the next main clause (many chondrites have experienced damage) is contrary to the information in the previous clause (chondrites are far from pristine).\n Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after \"though\"can’t be used in this way to join two main clauses."
