    "subtopicId": "boundaries",
    "subtopic": "Boundaries & punctuation",
    "difficulty": "hard",
    "passage": "In 2018, a team of researchers led by Dr. Caitlin Whalen compiled every available measurement of ocean mixing rates from the past two decades. With this novel data set, the team was able to determine how current-driven mixing varies across ______ and what impact it has on the distribution of heat and nutrients in the ocean.",
