    "subtopic": "Boundaries & punctuation",
    "difficulty": "hard",
    "passage": "Using satellite remote sensing, Dr. Catherine Nakalembe, director of NASA’s Harvest Africa initiative, gathers important data on crop health. Nakalembe doesn’t just compile the ______ she also shares her findings with African farmers, enabling them to make data-driven decisions about managing critical food crops.",
