    "explanation": "Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a semicolon to join a main clause (“Saville...novel”) and a second main clause (“she’s...it”) preceded by supplementary elements (“rather...narrative”).\n Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.\n Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses.\n Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after “novel” can’t be used in this way to join the two main clauses."
