    "explanation": "Choice C is the best answer. The convention being tested is the punctuation of a supplementary phrase following a clause. This choice uses a comma to separate the supplementary adverb phrase \"however\"from the independent clause it modifies (\"They...antiquity\") and uses a semicolon to join the first independent clause (\"They...antiquity\") and the second independent clause (\"some...literature\"). Further, placing the semicolon after \"however\"indicates that the information in the clause that this is part of (that neoclassical writers were not the first to adopt classical literary modes) is contrary to what might be assumed from the information in the previous sentence (that the neoclassical writers were unique in imitating classical epic poetry and satires).\n Choice A is incorrect because it fails to mark the boundary after \"however\"between the two independent clauses with appropriate punctuation.\n Choice B is incorrect because the comma after \"however\"can’t be used in this way to mark the boundary between the two independent clauses.\n Choice D is incorrect because placing the semicolon after \"antiquity\"illogically indicates that the information in the clause that this is part of (that prominent Renaissance figures were also influenced by classical literature) is contrary to the information in the previous clause (that neoclassical writers were not the first to adopt classical literary modes)."
